# Generated by container/bootstrap.sh - edit home/.bashrc.d/devbox.sh in the repo.
# shellcheck shell=bash

# OMP installs here so `omp update` works without an image rebuild.
export PATH="$HOME/.local/bin:$PATH"

# Node lives outside the bind-mounted home; /usr/local/bin holds symlinks for
# non-interactive SSH sessions, nvm is sourced here for interactive ones.
export NVM_DIR=/opt/nvm
export COREPACK_HOME=/opt/corepack
[ -s "$NVM_DIR/nvm.sh" ] && . "$NVM_DIR/nvm.sh"

export EDITOR=nano

eval "$(starship init bash)"

alias lg='lazygit'

# Run a command with secrets injected from 1Password, e.g. `devenv omp`.
# Needs an active `op` session: eval "$(op signin)".
devenv() {
  op run --env-file="$HOME/.config/devbox/secrets.env" -- "$@"
}
